EGB_st.name='EGB'; 
EGB_st.lat=44.231006;
EGB_st.lon=-79.783839;
EGB_st.alt=255;
EGB_st.env='con';
EGB_st.footp='RB';
%%

%EGB_rd=read_betsy_2026('C:\github_trend\raw_data\egb_neph_psap_clap',EGB_st.name);
%import via import tool

names_rd=fieldnames(EGB_rd);
for i=1:length(names_rd)-3
    EGB_rd.(names_rd{i})(EGB_rd.(names_rd{i})>999)=NaN;
end
EGB_rd.Properties.DimensionNames{1}='Time';
EGB_rd=retime(EGB_rd,'daily',@nanmedian);
names_rd=fieldnames(EGB_rd);
%%
datevec(EGB_rd.Time(1)) %[output:6101782b]
datevec(EGB_rd.Time(end)) %[output:12ac1c35]
prctile(EGB_rd.U1_S11,[5 50 95]) % up to 58% for 95 prct %[output:3ddf6836]

plotFigControl(EGB_rd,EGB_st.name); %[output:053b52f3] %[output:73d499e6] %[output:21d1578a] %[output:9051ad44] %[output:9a690c97] %[output:4eebfdea] %[output:18d5f512] %[output:3f35db0f]
% 1 size cut, ok
% sc: ok, no negatives,no clear seasonal cycle
%abs: no clear seasonality
%abs exp: clear seaonal cycle with max in winter
%%
% BP detection for scat coef and backscat

names_sc={'BsB1_S11', 'BsG1_S11', 'BsR1_S11'};
break_EGB_scat_BP=change_point_analysis_Def(EGB_rd,names_sc,0.05,'EGB','scattering'); %[output:5f65ab3f] %[output:20ecf05c] %[output:30482578] %[output:471853d8]
T_EGB_scat_BP=make_table_breakpoints_def(break_EGB_scat_BP);

names_bsc={'BbsB1_S11', 'BbsG1_S11', 'BbsR1_S11'};
break_EGB_bscat_BP=change_point_analysis_Def(EGB_rd,names_bsc,0.05,'EGB','Backscattering'); %[output:51e3a62a] %[output:329574ba] %[output:3a4d3f8d] %[output:89735dba]
T_EGB_bscat_BP=make_table_breakpoints_def(break_EGB_bscat_BP);
%%
%Homogeneisation PSAP CLAP with 30.4.2012-25.3.2015
Pt=timerange('2012-04-30','2015-03-25');
ratio_med_h=nanmedian(EGB_rd.BaG1_A12(Pt)./EGB_rd.BaG1_A11(Pt)) %1.07 %[output:6226d8d5]
ratio_STN_h=nanstd(EGB_rd.BaG1_A12(Pt)./EGB_rd.BaG1_A11(Pt)) % 2.018 %[output:47013047]
ratio_mean_h=nanmean(EGB_rd.BaG1_A12(Pt)./EGB_rd.BaG1_A11(Pt)) %1.04 %[output:01ed644d]
ratio_mean=nanmean(EGB_rd.BaG1_A12(Pt))/nanmean(EGB_rd.BaG1_A11(Pt)) % 1.0964 %[output:19cec55e]
ratio_median=nanmedian(EGB_rd.BaG1_A12(Pt))/nanmedian(EGB_rd.BaG1_A11(Pt)) % 1.07 %[output:4f1b9f65]
figure; %[output:9e32d758]
plot(EGB_rd.BaG1_A11(Pt),EGB_rd.BaG1_A12(Pt),'.'); %[output:9e32d758]

% fit between both data: slope 0.9785x+0.15
fit_test=robustfit(EGB_rd.BaG1_A11(Pt),EGB_rd.BaG1_A12(Pt)); % y coor=0.068, slope=0.9887

cte_psap1_clap3=1; % no homogeneisation

%%
% full abs data
P1=timerange('2009-01-01','2011-11-11');
P2=timerange('2012-04-30','2023-01-01');


EGB_rd.BaG1_Ah=NaN(size(EGB_rd.BaG1_A11));
EGB_rd.BaG1_Ah(P1)=EGB_rd.BaG1_A11(P1);
EGB_rd.BaG1_Ah(P2)=EGB_rd.BaG1_A12(P2);

EGB_rd.BaB1_Ah=EGB_rd.BaB1_A12;
EGB_rd.BaR1_Ah=EGB_rd.BaR1_A12;
%%
% BP detection for abs
names_abs={'BaB1_Ah','BaG1_Ah','BaR1_Ah'};
break_EGB_abs_BP=change_point_analysis_Def(EGB_rd,names_abs,0.05,'EGB','Absorption'); %[output:2385ce7f] %[output:56c918ac] %[output:91d88372] %[output:7c095a5d]
T_EGB_abs_BP=make_table_breakpoints_def(break_EGB_abs_BP);
%%
lambdaSC=[450;550;700];
lambdaAE=[467;530;660];

names_neph={'BsB1_S11', 'BsG1_S11', 'BsR1_S11','BbsB1_S11','BbsG1_S11','BbsR1_S11'};
EGB_expS=compute_exp_D(EGB_rd,names_neph,lambdaSC);
names_abs={'BaB1_Ah','BaG1_Ah','BaR1_Ah'};
EGB_expA=compute_exp_D(EGB_rd,names_abs,lambdaAE);
EGB_cal=outerjoin(EGB_expS,EGB_expA);

EGB_cal.SSAG1=EGB_rd.BsG1_S11./(EGB_rd.BsG1_S11+EGB_rd.BaG1_Ah);

plotFigControl_cal(EGB_cal, EGB_st.name); %[output:929993ce] %[output:499145c9] %[output:5806ba76]

% % % problem of expA==0
% % EGB_cal.expA_bg(EGB_cal.expA_bg==0)=NaN;
% % EGB_cal.expA_br(EGB_cal.expA_br==0)=NaN;
% % EGB_cal.expA_gr(EGB_cal.expA_gr==0)=NaN;
%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg', 'expS_br', 'expS_gr'};
break_EGB_exps_BP=change_point_analysis_Def(EGB_cal,names_exps,0.05,'EGB','scattering exp'); %[output:288106ef] %[output:4c8a1e62] %[output:9eca74ed] %[output:311631e8]
T_EGB_exps_BP=make_table_breakpoints_def(break_EGB_exps_BP); %[output:7a2c7d9c] %[output:4e29c50b] %[output:143d0c21] %[output:885327bd] %[output:931f83a4] %[output:5fa567a5] %[output:99a3bc5e] %[output:1a609cf5] %[output:982a9a33] %[output:5a78ce5c] %[output:926b11a3] %[output:601cbcbc] %[output:8acbbd72] %[output:9d0c19a9] %[output:71136626] %[output:234bbd70] %[output:282c7246] %[output:2ef76f1e] %[output:5621bf09] %[output:73d1acd0]
%%

names_exps={'expA_bg', 'expA_br', 'expA_gr'};
break_EGB_exps_BP=change_point_analysis_Def(EGB_cal,names_exps,0.05,'EGB','absorption exp'); %[output:722a45a2] %[output:999f9316] %[output:26d89dc6] %[output:6dd6ce08]
T_EGB_exps_BP=make_table_breakpoints_def(break_EGB_exps_BP);

names_BbF={'BbsFg'};
break_EGB_BbF_BP=change_point_analysis_Def(EGB_cal,names_BbF,0.05,'EGB','backscat fraction'); %[output:7d3805ff] %[output:113ee2c0]
T_EGB_BbF_BP=make_table_breakpoints_def(break_EGB_BbF_BP); %[output:4e87e411] %[output:4b5672ec]

names_SSA={'SSAG1'};
break_EGB_SSA_BP=change_point_analysis_Def(EGB_cal,names_SSA,0.05,'EGB','SSA'); %[output:9cc08cb2] %[output:7a86b904]
T_EGB_SSA_BP=make_table_breakpoints_def(break_EGB_SSA_BP); %[output:08585b67]

%%
%Questions:

%%
EGB_tr=outerjoin(EGB_rd,EGB_cal);
EGB_tr.y=year(EGB_tr.Time);
% begin at the beginning of a year: 2010
%end: 2025
P=timerange('2010-01-01','2026-01-01');
EGB_tr=EGB_tr(P,:);
%trend on U0_S11 has to be done: not constant U
%dry to use : also calculate exponent on dry if it is used
%AE31 not used: delete A81, only CAPS not used: deleter A12
%decide to use the time series with the max of CAPS (A00) due to better SSA: delete A11
names=fieldnames(EGB_tr);
c= startsWith(names,"U") | endsWith(names,["A11";"A12"]);
N=names(c);
for i=1:length(N)
    EGB_tr.(N{i})=[];
end
names=fieldnames(EGB_tr);

