EGB_tr.expS_gr=[];
%%
[EGB_result_MK,EGB_result_LMSlog,EGB_result_LMSlin]=all_trend_STN(EGB_tr,EGB_st); %[output:6d01b30b] %[output:228cdbf7] %[output:92d246e1] %[output:53f218a7] %[output:5cb0d8ea] %[output:2fd43ac7] %[output:72104fdd] %[output:7bab634f] %[output:206064ad] %[output:758276c9] %[output:4fde3f32] %[output:95fe529e] %[output:276fa4ca] %[output:78ac93f3] %[output:13a40b10] %[output:3cfb5314] %[output:63933b24] %[output:54cd04ff] %[output:3c28b63a] %[output:850c195c] %[output:637fddc4] %[output:721ce522] %[output:01f4a853] %[output:73738ede] %[output:738ba7b4] %[output:4bca66ee] %[output:52dbc71b] %[output:6e2fef4b] %[output:1ccc97f8] %[output:8a4dfdf5] %[output:97ea6606] %[output:9acb04d2] %[output:5359be5c] %[output:34010e7a] %[output:4813acc8] %[output:8a5c81ea] %[output:26cb9541] %[output:939b9b2b] %[output:443d5b34] %[output:17b435da] %[output:66fcbe5c] %[output:20a86d0b] %[output:43476835] %[output:6befa74d] %[output:7f1dd9ec] %[output:78543ed3]

writetable(EGB_result_MK,'EGB_res_MK.txt'); %, 'delimiter',',' )
writetable(EGB_result_LMSlog,'EGB_res_LMSlog.txt'); 
writetable(EGB_result_LMSlin,'EGB_res_LMSlin.txt'); 
